async function primeManualSeedArtists(token, selectedProfilesList, maxNewSearches = 2) {
  const rotation = loadSeedArtistRotation();
  const rows = [];
  for (const profile of selectedProfilesList || []) {
    for (const artist of profile.artists || []) {
      const key = normalizeArtistName(artist);
      if (!key) continue;
      rows.push({
        profileId: profile.id,
        artist,
        key,
        query: `artist:"${artist}"`,
        ageBonus: seedArtistAgeBonus(artist, rotation)
      });
    }
  }
  const unique = [...new Map(rows.map(row => [row.key, row])).values()];
  unique.sort((a, b) => {
    const aMain = a.profileId === "bartek" ? 1 : 0;
    const bMain = b.profileId === "bartek" ? 1 : 0;
    if (aMain !== bMain) return bMain - aMain;
    return b.ageBonus - a.ageBonus;
  });

  const startSearches = newSearchesThisGeneration;
  for (const row of unique) {
    if (newSearchesThisGeneration - startSearches >= maxNewSearches) break;
    if (candidatePoolForQueries([row.query]).length >= 3) continue;
    const offsets = searchOffsetsForQuery(row.query);
    const offset = offsets[0] ?? 0;
    await searchTracks(token, row.query, offset);
  }
}

async function primeProfileGenres(token, profilesToPrime, maxNewSearches = 6) {
  const byQuery = new Map();
  const state = loadGenrePrimeState();

  for (const profile of profilesToPrime || []) {
    const liked = new Set((profile.taste?.likedGenres || []).map(normalizeGenreName));
    const ok = new Set((profile.taste?.okGenres || []).map(normalizeGenreName));
    for (const genre of profile.genres || []) {
      const normalized = normalizeGenreName(genre);
      if (!normalized) continue;
      const query = `genre:"${normalized}"`;
      const key = canonicalQuery(query);
      const current = byQuery.get(key) || {
        query,
        key,
        genre: normalized,
        bartek: false,
        tasteLiked: false,
        tasteOk: false,
        supporters: 0,
        likedSupporters: 0,
        pool: candidatePoolForQueries([query]).length,
        lastPrimedAt: Number(state[key]?.lastPrimedAt || 0)
      };
      current.bartek ||= profile.id === "bartek";
      current.tasteLiked ||= liked.has(normalized);
      current.tasteOk ||= ok.has(normalized);
      current.supporters += 1;
      if (liked.has(normalized)) current.likedSupporters += 1;
      current.pool = Math.min(current.pool, candidatePoolForQueries([query]).length);
      byQuery.set(key, current);
    }
  }

  const candidates = [...byQuery.values()].sort((a, b) =>
    Number(a.pool > 0) - Number(b.pool > 0) ||
    a.lastPrimedAt - b.lastPrimedAt ||
    Number(b.tasteLiked) - Number(a.tasteLiked) ||
    b.likedSupporters - a.likedSupporters ||
    b.supporters - a.supporters ||
    Number(b.bartek) - Number(a.bartek) ||
    a.pool - b.pool ||
    a.genre.localeCompare(b.genre, "pl")
  );

  const before = newSearchesThisGeneration;
  for (const item of candidates) {
    if (newSearchesThisGeneration - before >= maxNewSearches) break;
    if (newSearchesThisGeneration >= maxNewSearchesThisGeneration) break;
    const offsets = searchOffsetsForQuery(item.query);
    if (!offsets.length) continue;
    await searchTracks(token, item.query, offsets[0]);
    state[item.key] = {
      genre: item.genre,
      lastPrimedAt: Date.now(),
      count: Number(state[item.key]?.count || 0) + 1
    };
  }
  saveGenrePrimeState(state);
}

async function primeCommonGroupQueries(token, selected, maxNewSearches = 3) {
  const common = [...tasteCommonGenreQueries(selected), ...exactCommonGenreQueries(selected)];
  const unique = [];
  const seen = new Set();

  for (const query of common) {
    const key = canonicalQuery(query);
    if (!key || seen.has(key) || wasQueryAttempted(query)) continue;
    seen.add(key);
    unique.push({
      query,
      pool: candidatePoolForQueries([query]).length
    });
  }

  unique.sort((a, b) => a.pool - b.pool);
  const before = newSearchesThisGeneration;
  for (const item of unique) {
    if (newSearchesThisGeneration - before >= maxNewSearches) break;
    if (newSearchesThisGeneration >= maxNewSearchesThisGeneration) break;
    const offsets = searchOffsetsForQuery(item.query);
    if (!offsets.length) continue;
    await searchTracks(token, item.query, offsets[0]);
  }
}
